package com.nimbusbill.customer.repository; import com.nimbusbill.customer.entity.TransactionCharge; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.Instant; import java.util.*;
public interface BillingChargeRepository extends JpaRepository<TransactionCharge,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select c from TransactionCharge c where c.customer.id=:customerId and c.currency=:currency and c.status='PENDING' and c.createdAt>=:start and c.createdAt<:end order by c.createdAt") List<TransactionCharge> lockPending(@Param("customerId") UUID customerId,@Param("currency") String currency,@Param("start") Instant start,@Param("end") Instant end);}
